// Generated by scripts/generate_sdk_wire_contract.py --write.
// Expected structs come from fixture values; wire bytes come from Python protobuf.
use prost::Message;
use serde_json::Value;

fn vectors() -> Vec<Value> {
    let gz = include_bytes!("../../../tests/conformance_vectors/wire_vectors.json.gz");
    let mut decoder = flate2::read::GzDecoder::new(&gz[..]);
    serde_json::from_reader::<_, Value>(decoder)
        .unwrap()["vectors"].as_array().unwrap().clone()
}

fn check<M: Message + Default + PartialEq + std::fmt::Debug>(vector: &Value, expected: M) {
    let wire = hex::decode(vector["wire_hex"].as_str().unwrap()).unwrap();
    let actual = M::decode(wire.as_slice()).unwrap();
    assert_eq!(actual, expected, "{}", vector["id"]);
    assert_eq!(M::decode(expected.encode_to_vec().as_slice()).unwrap(), expected);
    // Byte canonicality (R24): map fields use BTreeMap codegen, so sorted-key
    // re-encoding must reproduce the recorded corpus bytes exactly. prost
    // applies proto3 default-omission, so an explicit -0.0 (== 0.0) is
    // dropped while Python protobuf writes it; like the Elixir suite, vectors
    // whose re-encode stays length-stable are pinned byte-exact and the rest
    // stay pinned semantically.
    let reencoded = expected.encode_to_vec();
    if reencoded.len() == wire.len() {
        assert_eq!(reencoded, wire, "{}", vector["id"]);
    }
}

